export function buildAll() {
  let total = 0;
  for (const c of CFG) {
    const g = GRAM[c.key];
    total += build({
      id: c.id, section: 'grammar', level: c.level, minutes: c.minutes,
      title: c.title, titleAr: c.titleAr,
      objectives: [c.goal, 'Listen and type natural grammar-model sentences', 'Complete fill-blank, word-order and multiple-choice drills'],
      grammar: g,
      vocabulary: VOC[c.key],
      pools: c.pools,
    });
  }
  return { section: 'grammar', lessons: CFG.length, exercises: total };
}
